import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Parse text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find(item => item.role === 'headline') || items[0];
  const textContent = textItem?.text ?? 'Journal 2';

  // Create the card plane
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 1.0
  });

  const plane = new THREE.Mesh(geometry, material);
  plane.position.copy(new THREE.Vector3(0, 1, 0.06));
  group.add(plane);

  // Load and apply the image texture
  let textureCleanup = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.color.setHex(0xffffff);
    material.map = texture;
    material.needsUpdate = true;
    textureCleanup = () => texture.dispose();
  }).catch(() => {
    material.color.setHex(0x16161d);
  });

  // Add headline text
  const headlineObj = ctx.fontAtlas.createText(textContent, {
    fontSize: 39,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0
  });
  headlineObj.position.set(0, 0.28, 0.1);
  headlineObj.scale.multiplyScalar(0.008);
  group.add(headlineObj);

  // Apply parallax-scroll primitive
  const primResult = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.25,
    trigger: 'scroll'
  });

  // Animation state
  let isHovering = false;
  let hoverTimeline = null;
  let pressTimeline = null;

  // Hover effect: rise-in (0.15 scene units up, power3.out, 0.7s)
  const handleHover = () => {
    if (isHovering) return;
    isHovering = true;

    if (pressTimeline) pressTimeline.kill();
    if (hoverTimeline) hoverTimeline.kill();

    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: 1.15,
      duration: 0.7,
      ease: 'power3.out'
    }, 0);
  };

  const handleHoverOut = () => {
    if (!isHovering) return;
    isHovering = false;

    if (hoverTimeline) hoverTimeline.kill();

    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: 1,
      duration: 0.5,
      ease: 'power2.out'
    }, 0);
  };

  // Click effect: press-down (scale 0.97, 120ms, back.out) + emit navigate
  const handleClick = () => {
    if (pressTimeline) pressTimeline.kill();

    pressTimeline = gsap.timeline();
    pressTimeline.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }, 0);

    pressTimeline.to(group.scale, {
      x: 1,
      y: 1,
      duration: 0.3,
      ease: 'power2.out'
    }, 0.12);

    ctx.emit('navigate', { to: 'hub-journal' });
  };

  // Attach handlers
  group.userData.handlers = {
    hover: handleHover,
    hoverOut: handleHoverOut,
    click: handleClick
  };

  // Cleanup function
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    if (primResult?.cleanup) primResult.cleanup();
    if (textureCleanup) textureCleanup();
    geometry.dispose();
    material.dispose();
  };

  return group;
}
